mapper.select:
SELECT matched.kind, matched.id, matched.value FROM ( SELECT 'person' AS kind, p.id, p.name AS value FROM person p WHERE (p.workspace_id = #{workspaceId} OR EXISTS (SELECT 1 FROM person_share ps JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) org_workspace ON org_workspace.id = p.workspace_id WHERE ps.person_id = p.id AND ps.workspace_id = #{workspaceId})) AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND p.name IS NOT NULL
UNION ALL SELECT 'company' AS kind, c.id, c.name AS value FROM company c WHERE (c.workspace_id = #{workspaceId} OR EXISTS (SELECT 1 FROM company_share cs JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) org_workspace ON org_workspace.id = c.workspace_id WHERE cs.company_id = c.id AND cs.workspace_id = #{workspaceId})) AND c.archived_at IS NULL AND c.name IS NOT NULL
UNION ALL SELECT 'deal' AS kind, d.id, d.name AS value FROM deal d WHERE d.workspace_id = #{workspaceId} AND d.name IS NOT NULL
) matched WHERE matched.kind > #{afterKind} OR (matched.kind = #{afterKind} AND matched.id > #{afterId}) ORDER BY matched.kind, matched.id LIMIT #{limit}

SELECT 'person' AS kind, owned_window.id, p.name AS value, (p.id IS NOT NULL) AS needs_backfill
FROM (
  SELECT owned.id
  FROM person owned FORCE INDEX (idx_person_workspace)
  WHERE owned.workspace_id = #{workspaceId} AND owned.id > #{afterId}
  ORDER BY owned.id
  LIMIT #{limit}
) owned_window
LEFT JOIN person p ON p.id = owned_window.id AND p.workspace_id = #{workspaceId}
  AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL
  AND p.name IS NOT NULL
  AND NOT ()
ORDER BY owned_window.id

SELECT 'company' AS kind, owned_window.id, c.name AS value, (c.id IS NOT NULL) AS needs_backfill
FROM (
  SELECT owned.id
  FROM company owned FORCE INDEX (idx_company_workspace)
  WHERE owned.workspace_id = #{workspaceId} AND owned.id > #{afterId}
  ORDER BY owned.id
  LIMIT #{limit}
) owned_window
LEFT JOIN company c ON c.id = owned_window.id AND c.workspace_id = #{workspaceId}
  AND c.archived_at IS NULL
  AND c.name IS NOT NULL
  AND NOT ()
ORDER BY owned_window.id

SELECT 'deal' AS kind, owned_window.id, d.name AS value, (d.id IS NOT NULL) AS needs_backfill
FROM (
  SELECT owned.id
  FROM deal owned FORCE INDEX (idx_deal_workspace)
  WHERE owned.workspace_id = #{workspaceId} AND owned.id > #{afterId}
  ORDER BY owned.id
  LIMIT #{limit}
) owned_window
LEFT JOIN deal d ON d.id = owned_window.id AND d.workspace_id = #{workspaceId}
  AND d.name IS NOT NULL
  AND NOT ()
ORDER BY owned_window.id
